<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID();$product=wc_get_product($id); ?>
<article class="gmr-wrap gmr-artwork"><div class="gmr-artwork__gallery"><?php the_post_thumbnail('full'); foreach($product->get_gallery_image_ids() as $image_id) echo wp_get_attachment_image($image_id,'full'); ?></div><div class="gmr-artwork__info"><span class="gmr-kicker">Obra</span><div class="gmr-artwork__artist"><?php echo esc_html(gmr_theme_term_names($id,'gmr_artist'));?></div><h1><?php the_title();?></h1>
<dl class="gmr-facts"><?php $facts=array('Ano'=>gmr_theme_year($id),'Tecnica'=>gmr_theme_term_names($id,'gmr_technique'),'Soporte'=>gmr_theme_term_names($id,'gmr_support'),'Materiales'=>gmr_theme_term_names($id,'gmr_material'),'Medidas'=>gmr_theme_dimensions($id),'Coleccion'=>gmr_theme_term_names($id,'gmr_collection'));foreach($facts as $label=>$value)if($value)printf('<div class="gmr-fact"><dt>%s</dt><dd>%s</dd></div>',esc_html($label),esc_html($value));?></dl>
<div class="gmr-price"><?php echo gmr_theme_can_view_price($id)&&$product->get_price()?wp_kses_post($product->get_price_html()):'Consultar';?></div><p><?php echo esc_html(get_post_meta($id,'gmr_price_label',true));?></p><a class="gmr-button" href="<?php echo esc_url(home_url('/contacto/?obra='.$id));?>">Consultar obra</a><?php if(get_the_content())echo '<div class="gmr-editorial">'.wp_kses_post(wpautop(get_the_content())).'</div>';?></div></article>
<?php endwhile; get_footer(); ?>
